def f(h: int, w: int, n: int, grid: List[str]) -> Tuple[int, int, int]:
    from itertools import combinations
    count = [0]*26
    for row in grid:
        for c in row:
            if c!= '.':
                count[ord(c)-ord('A')] += 1
    count.sort()
    for target, x, y in zip(count, range(n, 1, -1), range(1, n+1, 1)):
        if x >= y:
            break
        else:
            row, col = 0, w
            while row < h:
                if col > 0:
                    col -= 1
                    if grid[row][col]!= '.':
                        x -= 1
                        y -= 1
                else:
                    break
                row += 1
            if x >= y:
                break
        if x < y:
            B = [ord('A')+i for i in range(n)]
            used = [False]*26
            dp = [True] + [False]*w
            for c in grid:
                for u in c:
                    if u == '.':
                        continue
                    dp[u-ord('A')+1] = not dp[u-ord('A')+1]
            for a, b in combinations(B, 2):
                if abs(a-b)!= n:
                    continue
                f = [i for i in range((b-a)%26+1)]
                f.sort()
                if f == [n//2]*n//2 + ([n//2+1]*n%2 if n%2 else []):
                    for i in range(h):
                        if not dp[ord(grid[i][0])-ord('A')]:
                            continue
                        row = i
                        col = 0
                        while col < w:
                            if used[ord(grid[row][col])-ord('A')]:
                                if col < w-1 and grid[row][col+1]!= '.':
                                    col += 1
                                continue
                            if col+1 < w and (ord(grid[row][col+1])-ord('A')-a)%26 == 0:
                                used[ord(grid[row][col])-ord('A')-a] = True
                            elif abs((ord(grid[row][col])-ord('A'))-a)%26 == abs((ord(grid[row][col+1])-ord('A'))-b) and (ord(grid[row][col])-ord('A')-a)%26!= 0:
                                if grid[row][col]!= '.':
                                    used[ord(grid[row][col])-ord('A')-a] = True
                                if col < w-1 and grid[row][col+1]!= '.':
                                    used[ord(grid[row][col+1])-ord('A')-b] = True
                            col += 1
                        if all(used):
                            return h, w, n
    return h, w, 1
